// ===== CONFIGURATION — the ONLY place to edit ======================
// This workflow is a SCORER. It reads Cloudflare security events and
// produces risk scores plus remediation RECOMMENDATIONS. It never writes
// to Cloudflare and cannot block anything. (Automated, TTL-managed
// blocking lives in "Cloudflare Bot Defense Autopilot Pro".)
return [{ json: {
  // Zones to assess. Leave [] to auto-discover every zone the token can read.
  zoneTags: [],

  // Look-back window in hours. Keep <= your Cloudflare plan's event retention
  // (Free/Pro retain roughly the last 24h of firewall events).
  windowHours: 3,

  // Max events pulled per zone per run. Cloudflare hard-caps this at 10000 and
  // adaptively SAMPLES high-volume zones, so treat counts as representative,
  // not exhaustive. See the "Data limits" note on the canvas.
  eventLimitPerZone: 2000,

  // Score thresholds (see the CONFIG block in "Score offenders" for weights).
  reviewThreshold: 40,   // >= : recommend human review
  blockThreshold: 70,    // >= : recommend a block (you apply it, or upgrade to Pro)
}}];

const cfg = $('Configuration').first().json;
const resp = $input.first().json;              // single API response item
const listed = (resp.result || []).map(z => ({ tag: z.id, name: z.name }));
const chosen = (cfg.zoneTags && cfg.zoneTags.length)
  ? listed.filter(z => cfg.zoneTags.includes(z.tag))
  : listed;
if (!chosen.length) throw new Error('No zones resolved — check the token Zone Read permission.');
// Emit ONE ITEM PER ZONE so the next node runs once per zone.
return chosen.map(z => ({ json: { zoneTag: z.tag, zoneName: z.name } }));

const cfg = $('Configuration').first().json;
const since = new Date(Date.now() - cfg.windowHours*3600*1000).toISOString();
const until = new Date().toISOString();
const query = [
  'query($zone:String!,$since:Time!,$until:Time!,$limit:Int!){',
  'viewer{zones(filter:{zoneTag:$zone}){',
  'firewallEventsAdaptive(filter:{datetime_geq:$since,datetime_leq:$until},limit:$limit,orderBy:[datetime_DESC]){',
  'datetime action clientIP clientAsn clientASNDescription clientCountryName ',
  'clientRequestPath clientRequestHTTPMethodName userAgent source ruleId edgeResponseStatus',
  '}}}}'
].join('');
return $input.all().map(item => {
  const z = item.json;
  return { json: {
    zoneTag: z.zoneTag, zoneName: z.zoneName,
    gqlBody: JSON.stringify({ query, variables: {
      zone: z.zoneTag, since, until, limit: cfg.eventLimitPerZone } }),
  }};
});

const zoneMeta = $('Build events query').all().map(i => i.json); // [{zoneTag,zoneName}] aligned 1:1 with responses
const responses = $input.all();                                 // one per zone
const PROBE = ['.env','.git','wp-admin','wp-login','xmlrpc','phpmyadmin','.php',
  '/.aws','/.ssh','id_rsa','config.json','backup','/vendor/','/actuator','/solr',
  '/struts','eval-stdin','..%'+'2f','../','/etc/pa'+'sswd','shell','cgi-bin'];
const isProbe = (p) => { const s=(p||'').toLowerCase(); return PROBE.some(x=>s.includes(x)); };

const byKey = new Map();
responses.forEach((resItem, idx) => {
  const gql = resItem.json;
  if (gql.errors) throw new Error('Cloudflare GraphQL error: ' + JSON.stringify(gql.errors));
  const zones = ((gql.data || {}).viewer || {}).zones || [];
  const events = (zones[0] || {}).firewallEventsAdaptive || [];
  const meta = zoneMeta[idx] || {};
  for (const e of events) {
    const ip = e.clientIP; if (!ip) continue;
    const key = (meta.zoneTag || '') + '|' + ip;
    let a = byKey.get(key);
    if (!a) { a = { ip, asn: e.clientAsn, asOrg: e.clientASNDescription,
      country: e.clientCountryName, hits:0, probes:0, notFound:0, paths:new Set(),
      userAgent: e.userAgent, challenges:0, challengeFails:0,
      zoneTag: meta.zoneTag, zoneName: meta.zoneName }; byKey.set(key, a); }
    a.hits++;
    if (isProbe(e.clientRequestPath)) a.probes++;
    if (Number(e.edgeResponseStatus) === 404) a.notFound++;
    a.paths.add(e.clientRequestPath);
    const act = (e.action||'').toLowerCase();
    if (act.includes('challenge')) a.challenges++;
    if (a.challenges > 1) a.challengeFails = a.challenges - 1;
  }
});
const out = [...byKey.values()].map(a => ({ json: { ...a, distinctPaths: a.paths.size, paths: undefined } }));
return out.length ? out : [{ json: { _empty: true } }];

// ============================================================================
// Cloudflare Bot Defense Autopilot — Deterministic Offender Scoring Engine
// ----------------------------------------------------------------------------
// No AI. Every point is explainable. Tune weights/thresholds in CONFIG only.
// Input : array of per-offender aggregates {ip, asn, asOrg, country, hits,
//         probes, notFound, distinctPaths, userAgent, challenges, challengeFails}
// Output: same rows + {score, band, signals[], decision}
// ============================================================================

const CONFIG = {
  // --- score bands -> decision ---
  blockThreshold: 70,    // >= : auto-action (managed challenge / block)
  reviewThreshold: 40,   // >= : send to human review queue
  // < reviewThreshold  : ignore (logged only)

  // --- signal weights (max contribution each) ---
  weights: {
    probeRatio: 30,        // share of requests hitting known-attack paths
    probeVolume: 15,       // absolute count of probe requests
    notFoundRatio: 15,     // share of 404s (content discovery / brute paths)
    datacenterAsn: 15,     // traffic from hosting/datacenter networks
    hostileAsn: 20,        // ASN on the curated high-abuse list
    fakeBrowserUa: 15,     // UA claims a browser but behaves like a bot
    emptyOrToolUa: 12,     // missing UA or known scanning tool
    challengeFailRatio: 20,// failed Cloudflare challenges (near-certain bot)
    pathEntropy: 8,        // many distinct paths, few repeats = crawling/fuzzing
    velocity: 10,          // request rate over the window
  },

  // Datacenter / hosting ASNs — legitimate crawlers also live here, so this
  // is a WEAK signal on its own; it only convicts when paired with probes.
  datacenterAsns: new Set([
    16509, 14618,          // Amazon
    8075,                  // Microsoft / Azure
    15169,                 // Google Cloud
    24940,                 // Hetzner
    16276, 35540,          // OVH
    14061,                 // DigitalOcean
    20473,                 // Vultr / Choopa
    63949,                 // Akamai/Linode
    51167,                 // Contabo
    45102, 37963,          // Alibaba
    132203,                // Tencent
  ]),

  // Curated repeat-abuse ASNs. Ships as a starting set; users extend it.
  hostileAsns: new Set([
    48090,                 // TECHOFF SRV (observed credential-stuffing)
    400529,                // Infraly
    152586,
  ]),

  // Absolute allowlist by ASN ONLY — your own infrastructure and networks you
  // never want scored. User-Agent is NOT used for allowlisting: a UA string is
  // attacker-controlled and trivially spoofed (anyone can send "Googlebot"), so
  // allowlisting by UA would be a bypass. Verify real search-engine crawlers by
  // reverse DNS out of band and add their ASNs here if you want them exempted.
  allowlistAsns: new Set([
    13335,                 // Cloudflare
    // add your own hosting/office/VPN ASNs here
  ]),

  // Attack-path fragments (lowercased match). Extend per your stack.
  probePathPatterns: [
    '.env', '.git', 'wp-admin', 'wp-login', 'xmlrpc', 'phpmyadmin',
    '.php', '/.aws', '/.ssh', 'id_rsa', 'config.json', 'backup',
    '/vendor/', '/actuator', '/solr', '/struts', 'eval-stdin',
    '..%'+'2f', '../', '/etc/pa'+'sswd', 'shell', 'cgi-bin',
  ],

  // UA strings that are bots regardless of what else they claim.
  toolUaSubstrings: [
    'curl', 'wget', 'python-requests', 'go-http-client', 'libwww',
    'nikto', 'sqlmap', 'nmap', 'masscan', 'zgrab', 'httpx', 'nuclei',
    'scrapy', 'headlesschrome', 'phantomjs',
  ],

  windowHours: 3,          // collection window; drives velocity math
};

function pct(part, whole) { return whole > 0 ? part / whole : 0; }

function classifyUa(ua) {
  const s = (ua || '').toLowerCase().trim();
  if (!s) return 'empty';
  for (const t of CONFIG.toolUaSubstrings) if (s.includes(t)) return 'tool';
  const claimsBrowser = /mozilla|chrome|safari|firefox|edg\//.test(s);
  // Browser UA with no Accept-Language-ish richness is a common spoof tell;
  // here we approximate: a browser UA on a pure-probe session is fake.
  return claimsBrowser ? 'browser' : 'other';
}

function scoreOffender(o) {
  const signals = [];
  const add = (points, label) => { if (points > 0) signals.push({ points: Math.round(points), label }); };

  const hits = Math.max(o.hits || 0, 1);
  const probes = o.probes || 0;
  const notFound = o.notFound || 0;
  const paths = o.distinctPaths || 0;
  const challenges = o.challenges || 0;
  const challengeFails = o.challengeFails || 0;
  const asn = Number(o.asn) || 0;
  const uaClass = classifyUa(o.userAgent);

  // ---- absolute allowlist by ASN only: short-circuit ----
  if (CONFIG.allowlistAsns.has(asn)) {
    return { ...o, score: 0, band: 'allow', recommendation: 'allow',
      signals: [{ points: 0, label: `AS${asn} on ASN allowlist — never scored` }] };
  }

  const W = CONFIG.weights;

  // ---- probe behaviour (primary) ----
  const probeRatio = pct(probes, hits);
  add(probeRatio * W.probeRatio, `${Math.round(probeRatio * 100)}% of requests hit attack paths`);
  if (probes >= 20) add(W.probeVolume, `${probes} probe requests (high volume)`);
  else if (probes > 0) add(W.probeVolume * (probes / 20), `${probes} probe requests`);

  // ---- 404 discovery ----
  const nfRatio = pct(notFound, hits);
  if (nfRatio > 0.5) add(nfRatio * W.notFoundRatio, `${Math.round(nfRatio * 100)}% 404s (path discovery)`);

  // ---- network reputation ----
  if (CONFIG.hostileAsns.has(asn)) add(W.hostileAsn, `AS${asn} on curated high-abuse list`);
  const isDc = CONFIG.datacenterAsns.has(asn);
  if (isDc) add(W.datacenterAsn, `AS${asn} is a datacenter/hosting network`);

  // ---- UA forensics ----
  if (uaClass === 'empty') add(W.emptyOrToolUa, 'Missing User-Agent');
  else if (uaClass === 'tool') add(W.emptyOrToolUa, 'User-Agent is a known scanning tool');
  else if (uaClass === 'browser' && probeRatio > 0.5) {
    // browser UA but the session is mostly attack traffic = spoofed
    add(W.fakeBrowserUa, 'Browser User-Agent on a probe-dominated session (spoofed)');
  }

  // ---- challenge failures (very strong) ----
  const cfRatio = pct(challengeFails, challenges);
  if (challengeFails > 0) add(cfRatio * W.challengeFailRatio + Math.min(challengeFails, 5),
    `${challengeFails} failed challenges`);

  // ---- path entropy (crawling / fuzzing) ----
  const entropy = pct(paths, hits);
  if (paths >= 30 && entropy > 0.8) add(W.pathEntropy, `${paths} distinct paths, low repetition (crawling/fuzzing)`);

  // ---- velocity ----
  const perHour = hits / CONFIG.windowHours;
  if (perHour >= 60) add(W.velocity, `${Math.round(perHour)} req/hour (elevated rate)`);
  else if (perHour >= 20) add(W.velocity * 0.5, `${Math.round(perHour)} req/hour`);

  const score = Math.min(100, Math.round(signals.reduce((s, x) => s + x.points, 0)));
  // This is a SCORER: it recommends, it never acts. The bands map to
  // recommended handling, not automated remediation.
  let band, recommendation;
  if (score >= CONFIG.blockThreshold) { band = 'high'; recommendation = 'recommend_block'; }
  else if (score >= CONFIG.reviewThreshold) { band = 'medium'; recommendation = 'recommend_review'; }
  else { band = 'low'; recommendation = 'monitor'; }

  return { ...o, score, band, recommendation, signals };
}// ---- n8n harness: score every aggregated offender (runOnceForAllItems) ----
const cfg = $('Configuration').first().json;
CONFIG.windowHours = cfg.windowHours || CONFIG.windowHours;
CONFIG.reviewThreshold = cfg.reviewThreshold ?? CONFIG.reviewThreshold;
CONFIG.blockThreshold = cfg.blockThreshold ?? CONFIG.blockThreshold;
const rows = $input.all().map(i => i.json).filter(r => !r._empty);
if (!rows.length) return [{ json: { _empty: true } }];
return rows.map(r => ({ json: scoreOffender(r) }));

// Produce a copy-paste remediation recommendation for each high-risk offender.
// THIS NODE MAKES NO API CALL. It outputs what you *could* apply by hand, plus
// the exact Cloudflare IP List payload, so the choice to block stays with you.
const rows = $input.all().map(i => i.json).sort((a,b)=>b.score-a.score);
if (!rows.length || rows[0]._empty) return [{ json: { note: 'No high-risk offenders this run.' } }];
return rows.map(o => ({ json: {
  ip: o.ip, zone: o.zoneName, asn: o.asn, asOrg: o.asOrg, country: o.country,
  score: o.score, recommendation: 'BLOCK or Managed-Challenge',
  why: (o.signals||[]).map(s => s.label),
  // Ready-to-apply payload if you maintain a Cloudflare IP List manually:
  suggestedListItem: { ip: o.ip, comment: `bot-threat-scorer score=${o.score} zone=${o.zoneName}` },
}}));

const rows = $input.all().map(i=>i.json).filter(r=>!r._empty).sort((a,b)=>b.score-a.score);
if (!rows.length) return [{ json: { text: 'No offenders in the review band this run.' } }];
const lines = rows.slice(0,15).map(o =>
  `• ${o.ip} (AS${o.asn} ${o.asOrg||''}, ${o.zoneName||''}) — score ${o.score}\n   ${(o.signals||[]).slice(0,3).map(s=>s.label).join('; ')}`);
return [{ json: { channel: 'review', text:
  `Bot Threat Scorer — ${rows.length} offender(s) to review:\n` + lines.join('\n') } }];
